t":"Huyện Tân Phước","name":"Cửa hàng Văn phòng phẩm Tân Phước","address_line":"ĐT867, thị trấn Mỹ Phước cũ, huyện Tân Phước (Plus Code F5FW+M77)","category":"van_phong_pham","phone":"02733848316","tax_code":null,"source_key":"gmap:ChIJoxV-MHq-CjEREZRzfGX69xk","source_url":"https://www.google.com/maps/search/?api=1&query=C%E1%BB%ADa%20h%C3%A0ng%20V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20T%C3%A2n%20Ph%C6%B0%E1%BB%9Bc%20M%E1%BB%B9%20Ph%C6%B0%E1%BB%9Bc%20Ti%E1%BB%81n%20Giang&query_place_id=ChIJoxV-MHq-CjEREZRzfGX69xk","verification_note":"Địa điểm hiện tại ghi xã Tân Phước 1 sau sáp nhập; nguồn Maps có phân loại novelty store cần kiểm tra mặt hàng."},{"district":"Huyện Tân Phước","name":"Văn phòng phẩm Phước Lộc","address_line":"Tổ 2 khu phố 3, thị trấn Mỹ Phước cũ, huyện Tân Phước","category":"van_phong_pham","phone":"0979490904","tax_code":null,"source_key":"gmap:ChIJh4PW3Pu_CjERf5wk0BGY0Ng","source_url":"https://www.google.com/maps/search/?api=1&query=VPP%20Ph%C6%B0%E1%BB%9Bc%20L%E1%BB%99c%20M%E1%BB%B9%20Ph%C6%B0%E1%BB%9Bc%20T%C3%A2n%20Ph%C6%B0%E1%BB%9Bc%20Ti%E1%BB%81n%20Giang&query_place_id=ChIJh4PW3Pu_CjERf5wk0BGY0Ng","verification_note":"Cần kiểm tra có cùng cơ sở với Photocopy Phước Lộc trên ĐT865 hay không; không tự cộng thêm điểm photocopy."},{"district":"Huyện Tân Phước","name":"Công ty Văn phòng phẩm Giai Phát","address_line":"Thửa 248, tờ bản đồ C3, ấp Mỹ Lộc, xã Thạnh Mỹ cũ, huyện Tân Phước","category":"van_phong_pham","phone":null,"tax_code":"1201673367","source_key":"tax:1201673367:giai-phat","source_url":"https://infodoanhnghiep.com/Tien-Giang/Huyen-Tan-Phuoc/trang-2/","verification_note":"Hồ sơ nhà cung cấp VPP; chưa chứng minh có quầy bán lẻ thực địa, cần Sales xác minh."},{"district":"Huyện Tân Phước","name":"Hộ kinh doanh VPP - Photocopy Nguyễn Trung","address_line":"Tổ 2, ấp 3, khu vực thị trấn Mỹ Phước cũ, huyện Tân Phước","category":"van_phong_pham","phone":null,"tax_code":"","source_key":"dth:082084013422:vpp-nguyentrung","source_url":"https://dauthau.asia/businesslistings/detail/Ho-kinh-doanh-Van-phong-pham-Photocoppy-Nguyen-Trung-215033/","verification_note":"Nguồn chính thức của hồ sơ nhà thầu ghi địa chỉ hiện hành xã Tân Phước 1; đơn vị đã cung ứng VPP cho trường học 2025-2026. MST 12 chữ số không khớp validation hiện tại, để trống chờ xác minh, không bịa."},{"district":"Huyện Tân Phước","name":"Trung tâm Bách hóa Tân Phước (có VPP)","address_line":"Khu phố 1, thị trấn Mỹ Phước cũ, huyện Tân Phước","category":"van_phong_pham","phone":null,"tax_code":null,"source_key":"congthuong:bachdhoa-tanphuoc","source_url":"https://kinhte.congthuong.vn/tien-giang-xay-dung-diem-ban-hang-viet-nam-tai-cac-xa-vung-sau-vung-xa-233815.html","verification_note":"Cơ sở bách hóa bán nhiều nhóm hàng trong đó có văn phòng phẩm, không phải nhà sách chuyên nghiệp."}]'::jsonb) AS x(
 district text,name text,address_line text,category text,phone text,tax_code text,
 source_key text,source_url text,verification_note text)
), ins AS(
 INSERT INTO public.field_prospects(
 id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,
 note,status,source_kind,research_source_key,research_source_url,research_batch)
 SELECT
 (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
 NULL,'ef943de4-18f7-49ef-8340-eefb18855534',
 s.name,s.address_line,'Tiền Giang',s.district,s.category,s.phone,nullif(s.tax_code,''),
 'Nguồn công khai 21/11/2026; chưa ghé, GPS chưa xác minh, còn cần Sales kiểm chứng hoạt động và mặt hàng. '||
 s.verification_note||' Nguồn: '||s.source_url,
 'new','manual',s.source_key,s.source_url,'2026-11-21-tien-giang-old-wave-01-four-districts'
 FROM src s
 WHERE s.district IN ('Thành phố Mỹ Tho','Huyện Châu Thành','Huyện Chợ Gạo','Huyện Tân Phước')
 AND s.source_url LIKE 'https://%'
 AND NOT EXISTS(SELECT 1 FROM public.customers c WHERE c.province='Tiền Giang' AND c.district=s.district
 AND lower(btrim(c.name))=lower(btrim(s.name)))
 AND NOT EXISTS(SELECT 1 FROM public.field_prospects p WHERE p.province='Tiền Giang' AND p.district=s.district
 AND (p.research_source_key=s.source_key OR (lower(btrim(p.name))=lower(btrim(s.name))
 AND lower(btrim(p.address_line))=lower(btrim(s.address_line)))))
 ON CONFLICT(research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING district,category,phone,tax_code
)
SELECT district,count(*)::int inserted,
 count(*) FILTER(WHERE category='nha_sach')::int bookstores,
 count(*) FILTER(WHERE category='van_phong_pham')::int stationery,
 count(*) FILTER(WHERE phone IS NOT NULL)::int phones,
 count(*) FILTER(WHERE tax_code IS NOT NULL)::int taxes
 FROM ins GROUP BY district ORDER BY district;